procedures.source:
fun p0(a) {
  r = p1(a);
  return r;
}
fun p1(a) {
  r = p2(a);
  return r;
}
fun p2(a) {
  r = p3(a);
  return r;
}
fun p3(a) {
  return a;
}
fun main() {
  x = p0(1);
  __voblint_check(x == 1);
}

